      font-size: 16px;
      line-height: 1.7;
    }

    :lang(ar) {
      letter-spacing: 0;
      text-transform: none;
      font-style: normal;
      line-height: 1.7;
    }

    button,
    input,
    textarea {
      font: inherit;
    }

    button {
      border: 0;
    }

    .phone {
      position: relative;
      display: flex;
      flex-direction: column;
      width: 100%;
      max-width: 430px;
      height: 100dvh;
      margin-inline: auto;
      overflow: hidden;
      background: var(--chat-bg);
      box-shadow: var(--shadow);
    }

    .status-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 30px;
      padding: calc(5px + var(--safe-top)) 20px 0;
      color: var(--ink);
      background: var(--surface);
      font-size: 13px;
      font-weight: 700;
      line-height: 1;
    }

    .status-icons {
      display: flex;
      align-items: center;
      gap: 6px;
    }

    .status-icons svg {
      display: block;
    }

    .app-header {
      position: relative;
      z-index: 2;
      display: flex;
      align-items: center;
      gap: 12px;
      min-height: 74px;
      padding: 12px 16px;
      color: #fff;
      background: var(--brand);
      box-shadow: 0 4px 16px rgba(7, 94, 84, 0.18);
    }

    .back-button,
    .call-button {
      display: grid;
      flex: 0 0 auto;
      width: 42px;
      height: 42px;
      place-items: center;
      border-radius: 50%;
      color: #fff;
      background: rgba(255, 255, 255, 0.11);
      cursor: pointer;
      transition: background 160ms ease, transform 160ms ease;
    }

    .back-button:active,
    .call-button:active {
      transform: scale(0.94);
      background: rgba(255, 255, 255, 0.2);
    }

    .back-icon {
      transform: scaleX(-1);
    }

    .agent-avatar {
      position: relative;
      display: grid;
      flex: 0 0 auto;
      width: 45px;
      height: 45px;
      place-items: center;
      border: 2px solid rgba(255, 255, 255, 0.68);
      border-radius: 50%;
      color: var(--brand-dark);
      background: var(--accent);
      font-size: 16px;
      font-weight: 800;
      line-height: 1;
    }

    .online-dot {
      position: absolute;
      inset-inline-end: -1px;
      inset-block-end: 1px;
      width: 12px;
      height: 12px;
      border: 2px solid var(--brand);
      border-radius: 50%;
      background: #52d273;
    }

    .agent-details {
      min-width: 0;
      flex: 1;
    }

    .agent-name {
      margin: 0;
      font-size: 17px;
      font-weight: 700;
      line-height: 1.5;
    }

    .agent-status {
      display: flex;
      align-items: center;
      gap: 5px;
      margin: 2px 0 0;
      color: rgba(255, 255, 255, 0.78);
      font-size: 14px;
      line-height: 1.7;
    }

    .header-action {
      padding: 6px 8px;
      color: #fff;
      background: transparent;
      cursor: pointer;
    }

    .header-action svg {
      display: block;
    }

    .conversation {
      flex: 1;
      min-height: 0;
      overflow-y: auto;
      overscroll-behavior: contain;
      padding: 18px 14px 20px;
      scrollbar-width: thin;
      scrollbar-color: #c9d5d2 transparent;
    }

    .date-divider {
      display: flex;
      align-items: center;
      gap: 10px;
      margin: 2px 0 18px;
      color: var(--muted);
      font-size: 14px;
      line-height: 1.7;
      text-align: center;
    }

    .date-divider::before,
    .date-divider::after {
      height: 1px;
      flex: 1;
      content: "";
      background: var(--line);
    }

    .message-row {
      display: flex;
      margin-bottom: 12px;
    }

    .message-row.user {
      justify-content: flex-start;
    }

    .message-row.agent {
      justify-content: flex-end;
    }

    .message-bubble {
      max-width: 84%;
      padding: 10px 13px 7px;
