    .message-row.agent .message-bubble {
      border-start-start-radius: 6px;
      border-end-start-radius: var(--radius);
      border-start-end-radius: var(--radius);
      border-end-end-radius: 6px;
      color: var(--ink);
      background: var(--bubble-agent);
