    .typing-dots i {
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: #8ca19d;
      animation: typing 1.2s infinite ease-in-out;
    }

    .typing-dots i:nth-child(2) {
      animation-delay: 120ms;
    }

    .typing-dots i:nth-child(3) {
      animation-delay: 240ms;
    }

    .composer {
      position: relative;
      z-index: 3;
      display: flex;
      align-items: flex-end;
      gap: 9px;
      padding: 10px 12px calc(10px + var(--safe-bottom));
      border-top: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.96);
      box-shadow: 0 -5px 18px rgba(32, 56, 52, 0.05);
      backdrop-filter: blur(12px);
    }

    .input-shell {
      display: flex;
      flex: 1;
      align-items: center;
      min-height: 48px;
      padding: 4px 6px 4px 14px;
      border: 1px solid #dce5e3;
      border-radius: 24px;
      background: #f7f9f9;
      transition: border-color 160ms ease, box-shadow 160ms ease;
    }

    .input-shell:focus-within {
      border-color: #78aaa3;
      box-shadow: 0 0 0 3px rgba(7, 94, 84, 0.1);
    }

    .attach-button {
      display: grid;
      flex: 0 0 auto;
      width: 38px;
      height: 38px;
      place-items: center;
      border-radius: 50%;
      color: var(--brand);
      background: transparent;
      cursor: pointer;
    }

    .message-input {
      width: 100%;
      min-width: 0;
      max-height: 112px;
      padding: 10px 8px;
      resize: none;
      border: 0;
      outline: 0;
      color: var(--ink);
      background: transparent;
      font-size: 16px;
      line-height: 1.7;
    }

    .message-input::placeholder {
      color: #8a9794;
      text-align: right;
    }

    .message-input:placeholder-shown {
      direction: rtl;
      text-align: right;
    }

    .send-button {
      display: grid;
      flex: 0 0 auto;
      width: 48px;
      height: 48px;
      place-items: center;
      border-radius: 50%;
      color: #fff;
      background: var(--brand);
      box-shadow: 0 5px 12px rgba(7, 94, 84, 0.22);
      cursor: pointer;
      transition: transform 150ms ease, background 150ms ease, opacity 150ms ease;
    }

    .send-button:active {
      transform: scale(0.92);
    }

    .send-button:disabled {
      opacity: 0.45;
      cursor: default;
      box-shadow: none;
    }

    .send-icon {
      transform: scaleX(-1);
    }

    @keyframes message-in {
      from {
        opacity: 0;
        transform: translateY(7px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes typing {
      0%,
      60%,
      100% {
        opacity: 0.45;
        transform: translateY(0);
      }
      30% {
        opacity: 1;
        transform: translateY(-2px);
      }
    }

    @media (max-width: 360px) {
      .message-bubble {
        max-width: 90%;
      }

      .app-header {
        padding-inline: 12px;
      }
    }

    @media (min-width: 500px) {
      body {
        padding: 18px 0;
      }

      .phone {
        height: calc(100dvh - 36px);
        min-height: 620px;
        border-radius: 28px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }
  </style>
