  <script>
    const input = document.getElementById("messageInput");
    const sendButton = document.getElementById("sendButton");
    const conversation = document.getElementById("conversation");
    const composer = document.getElementById("composer");
    const typingNote = document.getElementById("typingNote");

    function formatTime(date) {
      return new Intl.DateTimeFormat("ar-KW-u-nu-latn", {
        hour: "numeric",
        minute: "2-digit",
        hour12: true
      }).format(date);
    }

    function resizeInput() {
      input.style.height = "auto";
      input.style.height = Math.min(input.scrollHeight, 112) + "px";
      sendButton.disabled = input.value.trim().length === 0;
    }

    function scrollToLatest() {
      conversation.scrollTo({
        top: conversation.scrollHeight,
        behavior: "smooth"
      });
    }

    function createMessage(text, type) {
      const row = document.createElement("article");
      row.className = `message-row ${type}`;

      const bubble = document.createElement("div");
      bubble.className = "message-bubble";

      const paragraph = document.createElement("p");
      paragraph.className = "message-text";
      paragraph.dir = "auto";
      paragraph.textContent = text;

      const time = document.createElement("div");
      time.className = "message-time";

      const timeText = document.createElement("span");
      timeText.textContent = formatTime(new Date());
      timeText.dir = "ltr";

      const check = document.createElementNS("http://www.w3.org/2000/svg", "svg");
      check.setAttribute("viewBox", "0 0 16 16");
      check.setAttribute("fill", "none");
      check.setAttribute("aria-hidden", "true");

      const checkPath = document.createElementNS("http://www.w3.org/2000/svg", "path");
      checkPath.setAttribute("d", "m3 8 3 3 7-7");
      checkPath.setAttribute("stroke", "currentColor");
      checkPath.setAttribute("stroke-width", "1.7");
      checkPath.setAttribute("stroke-linecap", "round");
      checkPath.setAttribute("stroke-linejoin", "round");
      check.appendChild(checkPath);

      time.append(timeText, check);
      bubble.append(paragraph, time);
      row.appendChild(bubble);
      return row;
    }

    input.addEventListener("input", resizeInput);

    input.addEventListener("keydown", event => {
      if (event.key === "Enter" && !event.shiftKey) {
        event.preventDefault();
        composer.requestSubmit();
      }
    });

    composer.addEventListener("submit", event => {
      event.preventDefault();
      const text = input.value.trim();

      if (!text) return;

      conversation.appendChild(createMessage(text, "user"));
      input.value = "";
      resizeInput();
      scrollToLatest();

      typingNote.hidden = false;
      scrollToLatest();

      window.setTimeout(() => {
        typingNote.hidden = true;
        conversation.appendChild(
          createMessage(
            "وصلتني رسالتك بنجاح. هل هناك أي خطوة أخرى تحتاج إلى مساعدتي فيها؟",
            "agent"
          )
        );
        scrollToLatest();
      }, 1300);
    });

    resizeInput();
    scrollToLatest();
  </script>
